export const ASSERTIVE_EXPRESSION_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu asertif",q:"Bersikap 'asertif' berarti...",options:["Menyampaikan pendapat, perasaan, & kebutuhanmu dengan jujur & jelas, sambil tetap menghormati orang lain","Menang dalam perbedaan pendapat dan memaksakan kehendakmu kepada orang lain agar mereka menurut","Mengalah demi menghindari masalah, walaupun kebutuhanmu sendiri terabaikan dan tak dihargai oleh orang lain"],answer:0,explain:"Asertif ada di tengah: bukan menekan orang (agresif), bukan menekan diri sendiri (pasif).",hint:"Jujur + hormat, atau menang / mengalah selalu?"},
{n:2,type:"mcq",micro:"Pasif",q:"Perilaku 'pasif' dalam komunikasi:",options:["Menyampaikan kebutuhan dengan tenang dan jelas, sambil tetap menghormati perasaan lawan","Menahan pendapat & perasaan, ikut saja meski tidak setuju, lalu diam-diam kesal","Berteriak dan menyerang supaya suaramu didengar dan orang lain tak berani membantah"],answer:1,explain:"Pasif menghindari konflik sekarang tapi menumpuk kekesalan & membuat kebutuhanmu terabaikan.",hint:"Menahan & ikut saja, atau menyuarakan?"},
{n:3,type:"mcq",micro:"Agresif",q:"Perilaku 'agresif' dalam komunikasi:",options:["Diam saja dan menyimpan semuanya dalam hati supaya suasana tetap tenang dan damai","Menyampaikan kebutuhan sambil menghormati perasaan dan hak orang lain di sekitarmu","Menyampaikan kebutuhan dengan cara menyerang, menyalahkan, meremehkan, atau memaksa"],answer:2,explain:"Agresif menyuarakan diri tapi mengorbankan orang lain — membuat mereka defensif & merusak hubungan.",hint:"Menyerang untuk menang, atau menyuarakan dengan hormat?"},
{n:4,type:"mcq",micro:"Pernyataan 'aku'",q:"'Pernyataan aku' seperti 'Aku merasa kecewa waktu janji kita batal mendadak' lebih baik daripada 'Kamu selalu ingkar janji' karena...",options:["Fokus pada perasaan & situasi spesifik, bukan menyerang karakter orang, sehingga lebih mudah didengar","Terdengar lebih lemah & kurang meyakinkan, sehingga lebih baik langsung menuduh supaya tegas di depan orang","Menyembunyikan perasaanmu sepenuhnya supaya orang lain tidak tahu apa yang sebenarnya kamu rasakan di dalam hati"],answer:0,explain:"'Kamu selalu...' memicu pertahanan. 'Aku merasa... waktu...' membuka percakapan.",hint:"Fokus perasaan + situasi, atau menyerang karakter?"},
{n:5,type:"mcq",micro:"Menolak dengan sopan",q:"Menolak ajakan yang tidak kamu inginkan secara asertif:",options:["'Males ah, ajakanmu jelek terus, nggak seru buat aku.'","'Makasih udah ngajak, tapi kali ini aku nggak ikut ya.'","'Iya deh' (padahal tidak mau) lalu membatalkan diam-diam"],answer:1,explain:"Asertif: terima kasih + penolakan jelas + tanpa alasan berlebihan atau serangan.",hint:"Jelas & sopan, atau iya-terpaksa / menghina?"},
{n:6,type:"mcq",micro:"Meminta dengan jelas",q:"Cara asertif meminta bantuan:",options:["Berharap orang menawarkan sendiri lalu kesal kalau tidak","'Kamu harus bantu aku sekarang!'","'Bisa tolong bantu aku angkat ini? Berat kalau sendirian.'"],answer:2,explain:"Permintaan langsung + alasan singkat memberi orang kesempatan menjawab jujur.",hint:"Minta jelas, atau berharap / memaksa?"},
{n:7,type:"mcq",micro:"Menyuarakan ketidaknyamanan",q:"Teman meminjam barangmu tanpa izin lagi. Respons asertif:",options:["'Aku nggak nyaman kalau barangku dipakai tanpa bilang. Tolong izin dulu ya.'","Diam saja dan menahan kesal berhari-hari tanpa mengatakan apa-apa kepada temanmu","'Dasar nggak tahu diri! Kamu seenaknya pakai barang orang tanpa mikir!'"],answer:0,explain:"Sebut perilaku spesifik + perasaanmu + permintaan jelas. Bukan diam, bukan menghina.",hint:"Sebut perilaku + perasaan + permintaan, atau pendam / hina?"},
{n:8,type:"mcq",micro:"Nada asertif",q:"Nada suara yang asertif:",options:["Tinggi dan keras, menekan tiap kata supaya lawan tahu kamu serius","Tenang, jelas, volume sedang, mantap tapi tidak membentak","Sangat pelan dan ragu-ragu sampai hampir tak terdengar"],answer:1,explain:"Asertif terdengar tenang & yakin. Terlalu pelan = pasif; terlalu keras = agresif.",hint:"Tenang & mantap, atau ragu / membentak?"},
{n:9,type:"order",micro:"Menyampaikan keberatan dengan asertif",q:"Urutkan cara menyampaikan keberatan secara asertif.",items:["Sebut situasi spesifik: 'Waktu tadi kamu memutuskan sendiri tanpa tanya kelompok...'","Sebut perasaanmu: '...aku merasa nggak dianggap.'","Sebut yang kamu inginkan: 'Lain kali, aku mau kita putuskan bareng.'","Dengarkan tanggapannya"],answer:[0,1,2,3],explain:"Situasi → perasaan → permintaan → dengarkan. Ini pola pernyataan 'aku' yang lengkap.",hint:"Mulai dari fakta situasi, atau dari permintaan?"},
{n:10,type:"mcq",micro:"Asertif bukan kasar",q:"Bersikap asertif TIDAK berarti...",options:["Menyampaikan kebutuhanmu dengan jelas dan tenang kepada orang lain","Menghormati dirimu sendiri sekaligus menghargai hak orang lain","Menjadi kasar, dingin, atau tidak peduli perasaan orang lain"],answer:2,explain:"Asertif menjaga dua hal sekaligus: hakmu untuk bersuara & hak orang lain untuk dihormati.",hint:"Asertif = kasar, atau jelas + tetap hormat?"},
{n:11,type:"tf",micro:"Punya hak untuk bersuara",q:"Benar atau Salah: Kamu berhak menyampaikan pendapat, perasaan, & kebutuhanmu dengan sopan, meskipun orang lain mungkin tidak menyukainya.",answer:true,explain:"Menyuarakan diri dengan hormat adalah hakmu. Orang lain berhak menanggapi, tapi bukan berarti kamu harus diam.",hint:"Berhak bersuara dengan sopan, atau harus diam demi kenyamanan orang?"},
{n:12,type:"tf",micro:"Selalu mengalah itu baik?",q:"Benar atau Salah: Selalu mengalah & menyembunyikan pendapatmu demi menghindari konflik adalah cara terbaik menjaga hubungan jangka panjang.",answer:false,explain:"Sebaliknya, kekesalan yang dipendam terus menumpuk & sering meledak nanti, atau membuat hubungan terasa tidak jujur & tidak setara.",hint:"Memendam terus = hubungan sehat?"},
{n:13,type:"mcq",micro:"Menerima 'tidak'",q:"Kamu meminta sesuatu secara asertif & orang menolak. Respons yang dewasa:",options:["'Oke, aku hargai jawabanmu.' — kamu boleh kecewa tapi tidak memaksa atau merajuk","Terus mendesak sampai ia menyerah dan mengubah jawabannya menjadi 'ya'","Diam ngambek lama dan mengabaikannya sepanjang hari ini di depan teman"],answer:0,explain:"Asertif juga berarti menghormati hak orang lain untuk berkata tidak, sama seperti kamu berhak meminta.",hint:"Terima jawabannya, atau desak / ngambek?"},
{n:14,type:"mcq",micro:"Pasif-agresif",q:"'Pasif-agresif' adalah...",options:["Tersenyum tulus dan berkata terus terang tentang perasaanmu kepada orang yang membuatmu kesal setiap saat, walau sedang sibuk","Menyampaikan kekesalan secara tidak langsung: menyindir, mendiamkan, sengaja lambat, sambil berkata 'nggak apa-apa'","Menyampaikan kebutuhan dengan jujur & langsung kepada orang yang bersangkutan, tanpa sindiran maupun diam-diaman"],answer:1,explain:"Pasif-agresif membingungkan orang lain & tidak menyelesaikan masalah. Lebih baik jujur langsung.",hint:"Menyindir & mendiamkan, atau jujur langsung?"},
{n:15,type:"mcq",micro:"Memuji secara asertif",q:"Menyampaikan apresiasi juga bagian dari asertif. Contohnya:",options:["Diam saja meski kagum, karena memuji orang lain terlihat rendah","Memuji berlebihan meski tak tulus, supaya orang itu menuruti kemauanmu","'Aku suka caramu menjelaskan tadi, jadi lebih paham. Makasih ya.'"],answer:2,explain:"Asertif bukan hanya soal keluhan — menyuarakan hal positif secara spesifik & tulus juga termasuk.",hint:"Sebut hal spesifik yang kamu hargai, atau diam / berlebihan?"},
{n:16,type:"mcq",micro:"Menyampaikan perasaan tanpa meledak",q:"Kamu marah pada teman. Cara asertif (bukan agresif):",options:["Tunggu sampai cukup tenang, lalu: 'Aku marah soal kejadian tadi. Aku mau kita bicarakan.'","Langsung berteriak dan menyebutkan semua kesalahannya sejak dulu, supaya ia tahu betapa marahnya kamu","Diam dan memusuhi temanmu diam-diam tanpa menjelaskan apa yang membuatmu marah padanya"],answer:0,explain:"Asertif menyampaikan kemarahan sebagai informasi ('aku marah, mari bicara'), bukan sebagai serangan.",hint:"Tenang dulu lalu sampaikan, atau meledak / memusuhi?"},
{n:17,type:"mcq",micro:"Batas diri (boundary)",q:"'Batas diri' adalah...",options:["Sikap egois yang hanya memikirkan kebutuhan sendiri dan tidak peduli perasaan orang lain di sekitar","Aturan tentang apa yang boleh & tidak boleh dilakukan orang lain terhadapmu, yang kamu sampaikan dengan jelas","Tembok untuk menghindari orang lain, supaya mereka tak bisa mendekat atau meminta bantuan darimu"],answer:1,explain:"Contoh: 'Aku nggak mau dibentak. Kalau kamu bentak, aku akan pergi dulu sampai kita bisa bicara tenang.'",hint:"Aturan yang kamu sampaikan jelas, atau menghindari semua orang?"},
{n:18,type:"mcq",micro:"Meminta waktu",q:"Seseorang mendesakmu memutuskan sekarang & kamu belum siap. Respons asertif:",options:["'Iya deh, aku ikut keputusannya' lalu menyesal dan merasa terpaksa","'Jangan maksa-maksa dong! Aku nggak suka didesak begini!'","'Aku butuh waktu memikirkannya. Aku kabari besok ya.'"],answer:2,explain:"Meminta waktu adalah hak yang sah & bisa disampaikan dengan tenang.",hint:"Minta waktu dengan jelas, atau iya-terpaksa / marah?"},
{n:19,type:"mcq",micro:"Asertif di kelompok",q:"Dalam kerja kelompok, kamu diberi bagian yang tidak adil (paling banyak). Respons asertif:",options:["'Bagianku kelihatannya jauh lebih besar dari yang lain. Bisa kita bagi ulang lebih merata?'","Mengerjakan semuanya sendirian sambil kesal & mengeluh kepada orang lain di belakang anggota kelompok yang lain","'Kalian pemalas semua! Aku capek kerja sendiri, kalian cuma bisa duduk-duduk & menyuruh-nyuruh orang!'"],answer:0,explain:"Sebut fakta (pembagian tidak merata) + ajukan solusi (bagi ulang), tanpa menyerang.",hint:"Sebut fakta + usul solusi, atau pendam / menyerang?"},
{n:20,type:"open",micro:"Mengubah respons pasif & agresif jadi asertif",q:"Untuk situasi berikut, tulis satu respons PASIF, satu AGRESIF, dan satu ASERTIF: 'Temanmu berjanji mengembalikan uang Rp50.000 minggu lalu tapi belum juga, padahal kamu membutuhkannya.'",explain:"Jawaban baik menunjukkan tiga gaya jelas: pasif (diam/menunggu/berharap), agresif (menyerang karakter, mempermalukan, kata kasar), asertif (menyebut fakta janji + kebutuhan + permintaan jelas + sopan + opsi/penegasan waktu).",hint:"Pasif = diam & berharap; agresif = serang & hina; asertif = fakta + kebutuhan + permintaan jelas + sopan.",sample:"PASIF: (tidak berkata apa-apa, menunggu terus sambil kesal, mungkin berharap teman ingat sendiri). AGRESIF: 'Mana uang gue? Dasar nggak tahu diri, janji doang!' (menyerang karakter, mempermalukan). ASERTIF: 'Hei, minggu lalu kamu bilang mau balikin yang Rp50.000. Aku lagi butuh nih, bisa dikembalikan hari ini atau besok?' (menyebut fakta janji, menyebut kebutuhanku, meminta dengan jelas dan sopan, memberi opsi waktu). Kalau ia beralasan, aku tetap bisa menegaskan: 'Aku ngerti, tapi tolong dipastikan paling lambat Jumat ya.'"},
{n:21,type:"classify",micro:"Asertif vs agresif vs pasif",q:"Kelompokkan tiap kalimat ke 'Asertif', 'Agresif', atau 'Pasif'.",items:["'Aku nggak setuju, dan ini alasanku...'","'Terserah kamu aja deh.' (padahal tidak setuju)","'Kamu selalu salah, dengerin aku!'","'Aku mau giliranku dihargai juga.'"],groups:["Asertif","Agresif","Pasif"],answer:{"Asertif":["'Aku nggak setuju, dan ini alasanku...'","'Aku mau giliranku dihargai juga.'"],"Agresif":["'Kamu selalu salah, dengerin aku!'"],"Pasif":["'Terserah kamu aja deh.' (padahal tidak setuju)"]},explain:"Asertif: menyuarakan diri + hormat. Agresif: menyerang. Pasif: menahan & menyerah.",hint:"Menyuarakan + hormat, menyerang, atau menyerah?"},
{n:22,type:"mcq",micro:"Struktur pernyataan aku",q:"Pernyataan 'aku' yang lengkap biasanya berisi...",options:["Hanya kata 'aku' di depan tuduhan: 'Aku pikir kamu jahat'","Situasi spesifik + perasaan + kebutuhan/permintaan","Hanya tuduhan tentang orang lain"],answer:1,explain:"'Aku merasa X (perasaan) ketika Y (situasi), dan aku ingin Z (permintaan).' Menaruh 'aku' di depan tuduhan bukan pernyataan 'aku' sejati.",hint:"Situasi + perasaan + permintaan, atau tuduhan berkedok 'aku'?"},
{n:23,type:"mcq",micro:"Hambatan: takut tidak disukai",q:"Banyak orang sulit asertif karena takut...",options:["Terlihat terlalu pintar sehingga teman merasa tersaingi","Menjadi lebih bahagia sehingga orang lain iri dan menjauh","Membuat orang lain kecewa atau tidak menyukai mereka"],answer:2,explain:"Wajar merasa takut, tapi menyembunyikan kebutuhan demi disukai sering membuatmu lelah & tidak dihargai.",hint:"Takut tidak disukai, atau takut terlihat pintar?"},
{n:24,type:"mcq",micro:"Asertif & rasa bersalah",q:"Setelah menolak permintaan dengan sopan, kamu merasa bersalah. Cara pikir yang sehat:",options:["'Menolak dengan hormat bukan berbuat jahat. Aku boleh punya batas.'","'Aku orang jahat karena menolak, seharusnya aku tak boleh menolak.'","'Lain kali aku harus bilang iya saja supaya tidak merasa bersalah.'"],answer:0,explain:"Rasa bersalah setelah menolak adalah kebiasaan, bukan bukti kamu salah. Menolak dengan hormat itu wajar.",hint:"Menolak sopan = jahat, atau punya batas yang sah?"},
{n:25,type:"mcq",micro:"Menghadapi tekanan teman",q:"Teman-teman menekanmu ikut melakukan sesuatu yang kamu anggap salah. Respons asertif:",options:["'Kalian bodoh mau melakukan hal seperti itu! Pantas sering kena masalah!'","'Aku nggak mau ikut yang ini. Kalian silakan, tapi aku tetap nggak.'","'Iya deh, aku ikut saja, daripada dibilang nggak asik dan dijauhi.'"],answer:1,explain:"Asertif di bawah tekanan: pendirian jelas, tanpa menyerang, tanpa menyerah. Kamu tidak wajib menjelaskan panjang.",hint:"Pendirian jelas tanpa menyerang, atau ikut / menghina?"},
{n:26,type:"mcq",micro:"Asertif secara tertulis",q:"Menyampaikan keberatan lewat pesan teks secara asertif:",options:["Tulis dengan HURUF BESAR semua & banyak tanda seru supaya orangnya langsung tahu betapa seriusnya keberatanmu","Kirim pesan yang menyindir halus lalu tambahkan 'nggak apa-apa kok' supaya terlihat tidak marah, padahal kamu masih kesal","Tetap pakai pernyataan 'aku', spesifik, & sopan; baca ulang sebelum kirim agar tidak terdengar menyerang atau ambigu"],answer:2,explain:"Prinsip asertif sama di teks; hanya perlu ekstra hati-hati karena nada tidak terdengar.",hint:"Pernyataan 'aku' + sopan + baca ulang, atau kapital / menyindir?"},
{n:27,type:"tf",micro:"Asertif menghormati dua pihak",q:"Benar atau Salah: Komunikasi asertif berusaha menghormati kebutuhan dirimu DAN kebutuhan orang lain sekaligus, bukan mengorbankan salah satunya.",answer:true,explain:"Pasif mengorbankan dirimu; agresif mengorbankan orang lain; asertif mencari cara menghargai keduanya.",hint:"Menghargai dua pihak, atau mengorbankan salah satu?"},
{n:28,type:"tf",micro:"Asertif berarti selalu dapat yang diinginkan?",q:"Benar atau Salah: Kalau kamu sudah bersikap asertif dengan benar, kamu pasti akan selalu mendapatkan apa yang kamu minta.",answer:false,explain:"Sebaliknya, asertif adalah tentang menyampaikan dengan jujur & hormat — bukan jaminan hasil. Orang lain tetap berhak menolak, & itu bagian dari menghormati mereka.",hint:"Asertif = pasti dapat, atau menyampaikan dengan baik tanpa jaminan hasil?"},
{n:29,type:"mcq",micro:"Rusaknya 'aku' jadi 'kamu'",q:"'Aku merasa kamu memang sengaja mau menyakitiku' bukan pernyataan 'aku' yang baik karena...",options:["Menyelipkan tuduhan tentang niat orang lain, bukan perasaan & pengamatanmu sendiri","Terlalu jujur sehingga lawan bicara merasa tersinggung dan lebih marah","Terlalu pendek sehingga lawan bicara tidak paham maksud sebenarnya darimu"],answer:0,explain:"Pernyataan 'aku' sejati bicara tentang apa yang KAMU rasakan & amati, bukan menebak niat tersembunyi orang.",hint:"Perasaan & pengamatanmu, atau menuduh niat orang?"},
{n:30,type:"order",micro:"Menetapkan batas dengan tenang",q:"Urutkan cara menetapkan batas ketika teman terus mengejek dengan dalih bercanda.",items:["Sampaikan batas dengan jelas: 'Candaan soal fisikku bikin aku nggak nyaman. Tolong stop.'","Kalau berlanjut, ulangi sekali lagi dengan tegas tanpa marah berlebihan","Kalau tetap berlanjut, sebut konsekuensi: 'Kalau diterusin, aku milih menjauh dulu.'","Lakukan konsekuensinya bila perlu, tanpa drama"],answer:[0,1,2,3],explain:"Sampaikan batas → ulangi → sebut konsekuensi → jalankan. Batas tanpa konsekuensi yang ditepati mudah diabaikan.",hint:"Apa langkah pertama sebelum menyebut konsekuensi?"},
{n:31,type:"mcq",micro:"Asertif & emosi kuat",q:"Kalau kamu terlalu marah/sedih untuk bicara asertif sekarang, sebaiknya...",options:["Pendam saja dan berharap kekesalan hilang sendiri tanpa dibicarakan kepada orangnya","Tunda: 'Aku terlalu kesal buat ngomong sekarang. Kita bahas nanti setelah aku tenang.'","Paksakan bicara sekarang juga walau kamu kemungkinan besar meledak di depan orang"],answer:1,explain:"Menunda dengan menyebut alasan & waktu adalah pilihan asertif — bukan menghindar, bukan meledak.",hint:"Tunda dengan jelas, atau paksakan / pendam?"},
{n:32,type:"tf",micro:"Alasan berlebihan saat menolak",q:"Benar atau Salah: Saat menolak permintaan, kamu wajib memberikan daftar alasan yang panjang & meyakinkan, kalau tidak penolakanmu tidak sah.",answer:false,explain:"Sebaliknya, penolakan yang sopan & singkat sudah cukup ('Maaf, aku nggak bisa kali ini'). Alasan berlebihan sering malah terdengar seperti mencari-cari & mengundang debat.",hint:"Wajib alasan panjang, atau penolakan sopan singkat cukup?"},
{n:33,type:"mcq",micro:"Menerima kritik secara asertif",q:"Seseorang mengkritikmu. Respons asertif (bukan pasif menelan semua / agresif menolak semua):",options:["'Iya, aku memang payah. Kamu benar semua, aku mau berhenti mencoba.' (menelan semua)","'Kamu nggak berhak ngomong gitu soal aku! Pendapatmu salah semua!' (menolak semua)","'Terima kasih masukannya. Aku setuju soal X, tapi soal Y aku lihat berbeda karena...'"],answer:2,explain:"Asertif memilah kritik: terima bagian yang benar, sampaikan dengan tenang bagian yang kamu lihat berbeda.",hint:"Pilah & tanggapi, atau telan semua / tolak semua?"},
{n:34,type:"mcq",micro:"Asertif untuk orang lain (advokasi)",q:"Melihat teman diperlakukan tidak adil, sikap asertif:",options:["'Menurutku ini nggak adil buat dia. Bisa kita lihat lagi?' — bersuara untuk keadilan dengan tenang","Diam saja karena menurutmu itu bukan urusanmu, & lebih baik tidak ikut campur dalam masalah orang lain","Menyerang orang yang berbuat tidak adil itu dengan kata-kata kasar di depan banyak orang supaya ia merasa malu"],answer:0,explain:"Asertif juga bisa dipakai untuk membela orang lain — menyuarakan keberatan dengan hormat, bukan diam atau menyerang.",hint:"Bersuara tenang untuk keadilan, atau diam / menyerang?"},
{n:35,type:"mcq",micro:"Bahasa tubuh asertif",q:"Bahasa tubuh yang mendukung sikap asertif:",options:["Menunjuk-nunjuk, mendekat dengan sikap mengancam, dan wajah tegang","Berdiri/duduk tegak, kontak mata wajar, wajah tenang, suara stabil","Menunduk, suara bergetar, dan badan mundur menjauh dari lawan bicara"],answer:1,explain:"Tubuh yang tenang & tegak menyampaikan 'aku serius & aku menghormatimu' sekaligus.",hint:"Tegak & tenang, atau menunduk / mengancam?"},
{n:36,type:"mcq",micro:"Mengulang tanpa terpancing (broken record)",q:"Teman terus membujuk setelah kamu menolak. Teknik asertif:",options:["Meninggikan suara setiap kali mengulang jawabanmu supaya temanmu sadar bahwa kamu benar-benar jengkel","Menyerah pada bujukan yang ketiga kali karena sudah capek, lalu mengiyakan walaupun hatimu tidak mau","Ulangi inti jawabanmu dengan tenang tanpa terseret debat baru: 'Aku ngerti, tapi jawabanku tetap tidak.'"],answer:2,explain:"Mengulang pesan inti dengan tenang ('rekaman rusak') menahan tekanan tanpa harus bertengkar atau menyerah.",hint:"Ulangi tenang, atau meninggi / menyerah?"},
{n:37,type:"tf",micro:"Perasaan valid untuk disampaikan",q:"Benar atau Salah: Sebelum menyampaikan perasaanmu, kamu harus lebih dulu membuktikan bahwa perasaan itu 'benar' & bahwa orang lain seharusnya merasakan hal yang sama.",answer:false,explain:"Sebaliknya, perasaanmu adalah informasi yang sah untuk disampaikan tanpa perlu 'dibuktikan'. Menyampaikannya membuka jalan untuk saling memahami, meski orang lain merasa berbeda.",hint:"Perasaan sah disampaikan, atau harus dibuktikan dulu?"},
{n:38,type:"mcq",micro:"Asertif vs 'blak-blakan menyakiti'",q:"'Aku cuma jujur kok' kadang dipakai untuk membenarkan ucapan menyakiti. Beda asertif & itu:",options:["Asertif jujur TENTANG perasaan & kebutuhan sendiri dengan hormat; 'jujur menyakiti' menyerang atau menghina orang lalu berlindung di kata 'jujur'","Tidak ada bedanya, karena keduanya sama-sama mengatakan hal sebenarnya kepada orang lain dan sama-sama dianggap sikap jujur","Asertif berarti mengatakan semua yang terlintas di pikiran kepada lawan bicara, termasuk hal yang menyakitkan, tanpa disaring"],answer:0,explain:"Kejujuran yang asertif tetap memilih kata yang menghormati. Menyakiti lalu bilang 'kan jujur' bukan asertif.",hint:"Jujur + hormat, atau menyerang lalu berkedok jujur?"},
{n:39,type:"mcq",micro:"Menyesuaikan tanpa kehilangan inti",q:"Kamu bisa menyesuaikan CARA menyampaikan (lebih lembut ke adik kecil, lebih formal ke guru) tanpa...",options:["Menyembunyikan isi pesanmu agar terdengar sopan","Mengubah INTI pesan atau menyerah pada kebutuhanmu","Bersikap sopan karena sopan santun melemahkan asertif"],answer:1,explain:"Asertif fleksibel dalam bentuk, tegas dalam inti: pesan & kebutuhanmu tetap, gaya menyesuaikan pendengar.",hint:"Inti tetap, gaya menyesuaikan — atau menyerahkan inti?"},
{n:40,type:"open",micro:"Menulis pernyataan aku",q:"Susun pernyataan 'aku' yang lengkap (situasi + perasaan + permintaan) untuk situasi ini: 'Kakakmu sering masuk kamarmu tanpa mengetuk, termasuk saat kamu sedang ganti baju.' Lalu jelaskan tiap bagian pernyataanmu.",explain:"Jawaban baik menghasilkan pernyataan 'aku' dengan tiga bagian jelas — situasi spesifik (bukan 'selalu'/karakter), perasaan dengan 'aku merasa' (tanpa menuduh niat), permintaan konkret (tindakan, bukan kabur) — lalu menjelaskan fungsi tiap bagian.",hint:"Situasi = kejadian spesifik; perasaan = 'aku merasa...'; permintaan = tindakan konkret yang diinginkan.",sample:"Pernyataan 'aku': 'Kak, waktu Kakak masuk kamarku tanpa ngetuk tadi pas aku lagi ganti baju (situasi), aku merasa kaget dan nggak nyaman, kayak privasiku nggak dihargai (perasaan). Aku mau Kakak ketuk pintu dulu dan tunggu aku jawab sebelum masuk (permintaan).' Penjelasan tiap bagian: bagian SITUASI menyebut kejadian spesifik dan nyata, bukan 'Kakak selalu nyebelin', sehingga jelas apa yang dibahas. Bagian PERASAAN memakai kata 'aku merasa' untuk menyampaikan dampaknya padaku tanpa menuduh niat Kakak. Bagian PERMINTAAN menyebutkan tindakan konkret yang aku inginkan (ketuk lalu tunggu dijawab), bukan sekadar 'hargai aku dong' yang kabur. Aku menyampaikannya dengan nada tenang, bukan membentak dan bukan memendam."},
{n:41,type:"mcq",micro:"Skenario: dipotong terus saat bicara",q:"Dalam rapat, seseorang selalu memotong ucapanmu. Respons asertif:",options:["Diam dan tidak menyelesaikan kalimat, lalu membiarkannya terus memotong","'Kamu tuh nggak sopan! Doyan motong omongan, pantas nggak didengerin!'","'Boleh aku selesaikan dulu? Aku belum selesai tadi.' — tenang & jelas"],answer:2,explain:"Menegaskan hakmu menyelesaikan kalimat dengan tenang mengatur ulang giliran tanpa menyerang.",hint:"Tegaskan hakmu menyelesaikan, atau diam / menyerang?"},
{n:42,type:"mcq",micro:"Skenario: guru salah menilai",q:"Kamu yakin ada kesalahan dalam penilaian tugasmu. Respons asertif:",options:["'Bu, boleh saya tanya soal nilai nomor 4? Menurut saya jawaban saya sesuai kunci, mungkin saya keliru — bisa dicek bersama?'","Diam saja & menerima nilai itu apa adanya meskipun kamu yakin penilaiannya salah, supaya tidak dianggap rewel","'Ibu nggak becus meriksa! Ibu salah menilai pekerjaanku, tolong periksa ulang sekarang juga, Bu, sebelum rapor dibagikan!'"],answer:0,explain:"Sopan + spesifik + membuka kemungkinan kamu yang keliru = asertif yang menjaga hubungan & tetap menyuarakan hakmu.",hint:"Tanya spesifik & sopan, atau diam / menyerang?"},
{n:43,type:"mcq",micro:"Skenario: pujian yang ingin kamu sampaikan",q:"Temanmu diam-diam selalu membantu membersihkan kelas. Sikap asertif:",options:["Menganggapnya hal biasa dan tak berkata apa-apa, karena itu memang tugas dia","'Aku perhatiin kamu sering beresin kelas tanpa disuruh. Itu keren, makasih ya.'","Diam karena malu mengungkapkan apresiasi, lalu berharap ia sudah tahu"],answer:1,explain:"Menyuarakan apresiasi spesifik adalah bentuk asertif positif yang menguatkan hubungan & perilaku baik.",hint:"Sebut & apresiasi spesifik, atau diam?"},
{n:44,type:"mcq",micro:"Skenario: diminta berbohong",q:"Teman memintamu berbohong ke guru untuk menutupinya. Respons asertif:",options:["'Iya deh, aku bantu bohong' lalu berbohong kepada guru dan menyesal sepanjang minggu","'Kamu jahat banget minta aku bohong! Aku nggak mau berteman sama orang kayak kamu!'","'Aku nggak mau bohong soal ini. Aku bisa bantu kamu jelasin ke guru kalau kamu mau.'"],answer:2,explain:"Menolak melanggar nilaimu dengan jelas + menawarkan bantuan lain = asertif yang menjaga integritas & pertemanan.",hint:"Tolak + tawarkan bantuan lain, atau ikut / menghina?"},
{n:45,type:"order",micro:"Menyelesaikan konflik kecil secara asertif",q:"Urutkan langkah menyelesaikan salah paham dengan teman secara asertif.",items:["Ajak bicara berdua di waktu tenang: 'Aku mau ngobrolin soal kemarin.'","Sampaikan dengan pernyataan 'aku': situasi + perasaan","Dengarkan sudut pandangnya tanpa memotong","Cari solusi bersama & sepakati langkah ke depan"],answer:[0,1,2,3],explain:"Ajak bicara → sampaikan 'aku' → dengarkan → sepakati solusi. Bukan menyindir atau mendiamkan.",hint:"Apa yang dilakukan sebelum menyampaikan perasaan?"},
{n:46,type:"mcq",micro:"Skenario: teman pinjam uang lagi",q:"Teman yang belum lunas utang lama meminjam uang lagi. Respons asertif:",options:["'Yang kemarin belum kamu kembalikan. Aku nggak nyaman minjemin lagi sebelum itu beres.'","'Iya nih, aku pinjami' (padahal berat hati) lalu kesal sendiri berhari-hari karena merasa dimanfaatkan","'Dasar tukang ngutang! Utang lama saja belum lunas sudah berani minta pinjam lagi, tidak tahu malu!'"],answer:0,explain:"Menyebut fakta + batas dirimu dengan tenang. Kamu tidak wajib meminjamkan.",hint:"Sebut fakta + batas, atau iya-terpaksa / menghina?"},
{n:47,type:"mcq",micro:"Skenario: ditertawakan saat presentasi",q:"Beberapa teman menertawakanmu saat kamu presentasi. Setelahnya, respons asertif:",options:["Membalas dengan mempermalukan mereka di depan umum, supaya mereka tahu rasanya ditertawakan seperti itu","Ke mereka, berdua: 'Waktu aku presentasi tadi kalian ketawa. Itu bikin aku nggak nyaman. Tolong jangan gitu lain kali.'","Menangis diam-diam lalu menolak presentasi lagi seumur hidup supaya tidak ditertawakan orang lain di depan kelas"],answer:1,explain:"Menyampaikan dampak perilaku mereka + permintaan jelas, di waktu & tempat yang tepat.",hint:"Sampaikan dampak + permintaan berdua, atau menyerah / membalas?"},
{n:48,type:"mcq",micro:"Skenario: orang tua membandingkanmu",q:"Orang tua sering membandingkanmu dengan sepupu. Respons asertif & sopan:",options:["Membentak dan pergi sambil membanting pintu karena merasa dibandingkan terus dengan sepupu, lalu tak mau bicara","Diam dan menyimpan luka bertahun-tahun karena takut dianggap melawan atau durhaka kepada Ibu sendiri di rumah","'Bu, waktu aku dibandingin sama sepupu, aku jadi ngerasa usahaku nggak keliatan. Aku mau dinilai dari perkembanganku sendiri.'"],answer:2,explain:"Kamu bisa asertif ke orang tua dengan nada hormat: sebut situasi, perasaan, & yang kamu butuhkan.",hint:"Sampaikan perasaan dengan hormat, atau membentak / memendam?"},
{n:49,type:"mcq",micro:"Skenario: ajakan yang membuatmu ragu",q:"Teman mengajak ke tempat yang kamu ragu aman. Respons asertif:",options:["'Aku kurang sreg ke sana. Gimana kalau kita cari tempat lain?'","'Ayo aja deh' lalu cemas sepanjang jalan tanpa menyampaikan keraguanmu","'Idemu bahaya terus! Kamu nggak mikir keselamatan, makanya aku nggak ikut!'"],answer:0,explain:"Menyuarakan keraguan + menawarkan alternatif menjaga keselamatan & pertemanan.",hint:"Suarakan keraguan + alternatif, atau ikut cemas / menghina?"},
{n:50,type:"open",micro:"Merancang percakapan asertif",q:"Kamu selalu jadi orang yang dimintai tolong menggantikan piket teman-teman, sampai piketmu sendiri terbengkalai. Rancang percakapan asertif yang akan kamu lakukan dengan kelompok piket: apa yang akan kamu katakan, bagaimana jika mereka membujuk, dan batas apa yang kamu tetapkan.",explain:"Jawaban baik memuat: pernyataan 'aku' dengan situasi + perasaan + perubahan yang diminta; strategi menghadapi bujukan (mengulang tenang, tidak over-justifikasi, tidak merasa bersalah); dan batas konkret yang terukur (frekuensi maksimal, pemberitahuan sebelumnya, konsekuensi bila dipaksa).",hint:"Nyatakan pola + perasaan + aturan baru; siapkan kalimat ulang untuk bujukan; tetapkan batas yang bisa diukur.",sample:"Yang akan kukatakan: 'Teman-teman, beberapa minggu ini aku hampir selalu yang gantiin piket kalian, dan akibatnya piket serta tugasku sendiri jadi keteteran. Aku merasa dimanfaatkan, walau mungkin kalian nggak sengaja. Mulai sekarang aku cuma bisa bantu gantiin kalau benar-benar darurat dan diminta jauh-jauh hari, bukan mendadak.' Jika mereka membujuk ('sekali ini aja', 'kamu kan biasanya mau'): aku pakai teknik mengulang tenang — 'Aku ngerti kalian lagi repot, tapi hari ini aku nggak bisa. Coba cari yang lain ya.' Aku tidak perlu memberi alasan berlebihan atau merasa bersalah. Batas yang kutetapkan: (1) aku hanya menggantikan piket maksimal sekali sebulan; (2) permintaan harus disampaikan minimal sehari sebelumnya, bukan mendadak; (3) kalau ada yang memaksa atau menyindir, aku akan berkata sekali lagi dengan tegas lalu mengakhiri pembicaraan. Aku juga akan mengapresiasi kalau nanti mereka mulai piket sendiri."},
{n:51,type:"mcq",micro:"Skenario: menyampaikan kebutuhan berbeda",q:"Kelompok mau belajar sambil dengar musik keras, tapi kamu tidak bisa fokus begitu. Respons asertif:",options:["'Selera musik kalian norak banget! Matiin sekarang juga, aku nggak bisa belajar kalau dengar lagu sampah!'","'Aku susah fokus kalau musiknya keras. Bisa dikecilin, atau aku pakai headphone sendiri aja?'","Memaksakan diri tetap duduk di situ dan akhirnya tidak paham belajar kelompok tanpa bilang apa-apa"],answer:1,explain:"Sebut kebutuhanmu + tawarkan beberapa solusi. Kebutuhan berbeda bisa dijembatani.",hint:"Sebut kebutuhan + solusi, atau memaksakan diri / menghina?"},
{n:52,type:"tf",micro:"Asertif butuh latihan",q:"Benar atau Salah: Bersikap asertif terasa canggung pada awalnya, terutama bagi orang yang terbiasa pasif, dan menjadi lebih alami dengan latihan berulang di situasi kecil.",answer:true,explain:"Mulai dari hal kecil (mengembalikan pesanan yang salah, meminta kursi yang kamu pesan) membangun kebiasaan untuk situasi besar.",hint:"Langsung mahir, atau canggung dulu lalu terlatih?"},
{n:53,type:"mcq",micro:"Skenario: teman curhat lalu menuntut kamu setuju",q:"Teman curhat & menuntut kamu setuju bahwa dia 100% benar, padahal kamu lihat ada sisi lain. Respons asertif:",options:["'Iya, kamu benar banget, seratus persen' (padahal kamu tidak yakin) supaya temanmu senang & tidak marah","'Ya salah kamu sendiri sih, makanya jangan suka begitu, aku sudah bilang dari dulu tapi kamu nggak pernah dengar.'","'Aku ngerti kamu kesal & aku di pihakmu sebagai teman. Tapi jujur, aku juga lihat bagian di mana kamu bisa bersikap beda.'"],answer:2,explain:"Asertif menyeimbangkan dukungan & kejujuran: akui perasaan, tetap sampaikan pandanganmu dengan lembut.",hint:"Dukung + jujur lembut, atau setuju palsu / menyalahkan?"},
{n:54,type:"mcq",micro:"Skenario: dipuji untuk hal yang bukan kamu",q:"Guru memujimu untuk ide yang sebenarnya dari temanmu. Respons asertif & jujur:",options:["'Terima kasih Bu, tapi sebenarnya ide itu dari Sinta. Dia yang pertama mengusulkan.'","Diam saja & menerima pujian yang sebenarnya bukan hakmu, supaya suasana kelas tidak jadi canggung","Malah menjelekkan Sinta di depan guru supaya pujiannya hanya jatuh kepadamu & orang lain tidak ikut tahu"],answer:0,explain:"Asertif juga berarti jujur meski merugikanmu sedikit — mengakui kontribusi orang lain dengan jelas.",hint:"Luruskan & akui temanmu, atau diam menikmati pujian?"},
{n:55,type:"mcq",micro:"Skenario: menagih janji dengan tenang",q:"Seseorang berjanji membantu proyekmu lalu menghilang. Respons asertif:",options:["'Kamu emang nggak bisa diandalkan! Janjimu omong kosong, aku nggak akan percaya lagi sama kamu!'","'Kamu bilang mau bantu bagian desain. Aku butuh kepastian: kamu masih bisa, atau aku cari orang lain?'","Mengerjakan semuanya sendiri sambil kesal di dalam hati dan tidak bilang apa-apa kepada yang menghilang"],answer:1,explain:"Sebut janji + minta kepastian + sebut opsi. Ini menjaga proyek tanpa menyerang.",hint:"Sebut janji + minta kepastian, atau pendam / menyerang?"},
{n:56,type:"mcq",micro:"Skenario: asertif ke penjual",q:"Kamu menerima pesanan makanan yang salah. Respons asertif:",options:["Memakannya saja meski bukan yang dipesan, lalu kecewa dan diam","Marah-marah dan menghina pelayan di depan pengunjung supaya ia kapok","'Maaf, pesanan saya tadi ayam, ini ikan. Bisa tolong ditukar?'"],answer:2,explain:"Sebut fakta + permintaan jelas + sopan. Kamu berhak mendapat yang kamu pesan.",hint:"Sebut fakta + minta tukar, atau terima / marah?"},
{n:57,type:"tf",micro:"Menghormati 'tidak' dari orang lain",q:"Benar atau Salah: Kalau kamu sudah menyampaikan permintaan dengan asertif & benar, orang lain tidak berhak menolaknya atau menetapkan batas terhadapmu.",answer:false,explain:"Sebaliknya, hak untuk bersuara berlaku dua arah. Kamu boleh meminta; mereka boleh menolak; bersikap asertif termasuk menghormati 'tidak' mereka tanpa merajuk atau memaksa.",hint:"Batas berlaku dua arah, atau hanya untukmu?"},
{n:58,type:"mcq",micro:"Skenario: kelompok mengabaikan idemu",q:"Kamu mengusulkan sesuatu tapi selalu diabaikan tanpa dibahas. Respons asertif:",options:["'Aku sudah beberapa kali usul soal ini tapi belum sempat dibahas. Boleh kita pertimbangkan sebentar?'","Berhenti berkontribusi di kelompok itu karena merasa usulanmu akan tetap diabaikan, lalu mengerjakan hal lain","'Kalian nggak dengerin aku! Kalian pilih kasih dan cuma mau ide dari teman dekat kalian saja!'"],answer:0,explain:"Menyebut pola (diabaikan) + meminta ruang pembahasan, tenang & spesifik.",hint:"Sebut pola + minta ruang bahas, atau menyerah / menuduh?"},
{n:59,type:"mcq",micro:"Skenario: menetapkan batas waktu belajar",q:"Teman sering meneleponmu larut malam untuk mengobrol santai, mengganggu tidurmu. Respons asertif:",options:["Memblokir nomornya tanpa penjelasan supaya ia tak bisa lagi menelepon di larut malam, lalu tidur","'Aku senang ngobrol sama kamu, tapi aku butuh tidur sebelum jam 10. Bisa kita ngobrolnya sore aja?'","Menjawab telepon tiap malam sambil mengantuk dan kesal di dalam hati, tanpa mengatakan apa-apa"],answer:1,explain:"Hargai hubungannya + sebut kebutuhanmu + tawarkan alternatif waktu. Batas yang jelas & ramah.",hint:"Hargai + sebut kebutuhan + alternatif, atau menurut / memblokir diam-diam?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu dan seorang teman selalu ditugaskan berpasangan, tetapi ia hampir tidak pernah mengerjakan bagiannya sehingga kamu kelelahan dan nilaimu ikut terpengaruh. Kamu takut ia tersinggung dan pertemanan rusak. Rancang pendekatan asertif menyeluruh: persiapan, apa yang kamu katakan, cara menghadapi berbagai reaksi, dan langkah bila tidak ada perubahan.",explain:"Jawaban baik mencakup: persiapan (waktu/tempat tepat, menenangkan diri, contoh spesifik); pernyataan 'aku' berisi situasi + perasaan + permintaan konkret; respons berjenjang untuk reaksi berbeda (menerima, defensif, menuduh) dengan tetap tenang & fokus pada kebutuhan; dan langkah eskalasi yang wajar (bicara ke guru berdasar fakta, minta pindah kelompok) tanpa menyebarkan gosip.",hint:"Persiapan + pernyataan 'aku' + cara tetap tenang menghadapi bujukan/tuduhan + eskalasi berbasis fakta ke guru.",sample:"Persiapan: aku memilih waktu tenang berdua (bukan di depan orang, bukan saat buru-buru), dan menenangkan diriku dulu supaya tidak bicara dengan marah. Aku juga menyiapkan contoh spesifik (tugas mana, bagian apa yang tidak dikerjakan). Apa yang kukatakan (pernyataan 'aku'): 'Aku mau ngomongin soal tugas kita. Beberapa kali terakhir, bagianmu belum dikerjakan sampai mendekati tenggat, jadi aku yang menyelesaikan hampir semuanya. Aku merasa kelelahan dan khawatir soal nilai kita. Aku pengin kita bagi tugas yang jelas dan masing-masing pegang bagiannya.' Menghadapi reaksi: (a) kalau ia minta maaf dan berjanji berubah — aku terima dengan baik dan usulkan cara konkret (bagi tugas tertulis, cek di tengah). (b) kalau ia defensif ('kamu juga nggak sempurna') — aku tetap tenang: 'Mungkin, tapi sekarang aku lagi ngomongin bagian tugas ini. Aku butuh kamu pegang bagianmu.' (c) kalau ia menuduh aku merusak pertemanan — 'Justru karena aku mau kita tetap baik, aku milih ngomong langsung daripada diam dan kesel.' Bila tidak ada perubahan setelah aku sudah menyampaikan dengan jelas dan memberi kesempatan: aku bicara ke guru dengan tenang dan berdasar fakta, menjelaskan pembagian kerja yang sebenarnya dan meminta agar penilaian mempertimbangkan kontribusi masing-masing, atau meminta ditempatkan di kelompok berbeda. Aku tidak menyebarkan keburukannya ke teman lain."},
{n:61,type:"mcq",micro:"Mengapa pasif merugikan jangka panjang",q:"Mengapa terus-menerus pasif (menahan kebutuhan) merugikan hubungan?",options:["Tak ada kerugian, justru semua senang dan hubungan tetap damai karena kamu tak pernah menolak, sehingga kamu dikenal baik","Membuatmu dihormati dan disegani, sehingga hubungan justru menjadi lebih setara dan kuat di kelompok","Kekesalan menumpuk & bisa meledak; hubungan jadi tidak setara & tidak jujur; orang lain tak tahu ada masalah"],answer:2,explain:"Orang tidak bisa memperbaiki apa yang tidak mereka ketahui. Diam menghilangkan kesempatan itu.",hint:"Menumpuk & meledak, atau semua baik-baik saja?"},
{n:62,type:"mcq",micro:"Mengapa agresif juga gagal",q:"Mengapa gaya agresif sering gagal mencapai tujuan?",options:["Membuat orang defensif atau melawan balik, merusak kepercayaan, & masalah inti tak terselesaikan","Berhasil membuat orang menurut dalam jangka panjang, sehingga masalah inti terselesaikan dan hubungan makin erat","Membuat orang lain lebih menyukaimu dan menghormatimu, karena mereka takut dan segan terhadap sikapmu"],answer:0,explain:"Menang lewat menekan sering hanya sementara & meninggalkan dendam. Asertif membangun solusi yang bertahan.",hint:"Menang sesaat + dendam, atau solusi yang bertahan?"},
{n:63,type:"tf",micro:"Asertif & harga diri",q:"Benar atau Salah: Melatih diri menyampaikan kebutuhan & batas dengan hormat cenderung menumbuhkan harga diri, karena kamu memperlakukan pendapat & perasaanmu sebagai hal yang berharga.",answer:true,explain:"Setiap kali kamu bersuara dengan hormat & bertahan pada batas yang sah, kamu menguatkan pesan ke dirimu: 'aku layak didengar'.",hint:"Bersuara hormat menumbuhkan harga diri, atau tak berpengaruh?"},
{n:64,type:"mcq",micro:"Membedakan asertif & keras kepala",q:"Beda 'asertif' & 'keras kepala':",options:["Asertif berarti tak berubah pikiran meski ada alasan baru dari lawan bicara, dan itu tanda pendirian kuat","Asertif menyampaikan posisi dengan jelas TAPI tetap mau mendengar & mempertimbangkan; keras kepala menolak semua masukan","Keduanya sama, karena sama-sama mempertahankan pendapat dan enggan mengubah sikap di depan orang lain"],answer:1,explain:"Asertif tegas soal hak & kebutuhan inti, tapi terbuka pada informasi baru & kompromi yang adil.",hint:"Jelas + tetap mendengar, atau menutup semua masukan?"},
{n:65,type:"mcq",micro:"Mengapa pernyataan 'aku' bekerja",q:"Mengapa 'Aku merasa X ketika Y' lebih efektif daripada 'Kamu selalu Y'?",options:["Ia menyembunyikan masalah, sehingga lawan bicara tak tahu bahwa kamu sebenarnya sedang kesal, agar suasana damai","Ia membuat kamu terdengar menyerah & lemah di depan lawan bicara, sehingga kebutuhanmu tidak akan dianggap serius","Ia menyampaikan dampak nyata padamu tanpa menuduh, sehingga lawan bicara tidak langsung defensif & bisa mendengar"],answer:2,explain:"'Kamu selalu' terasa seperti serangan & memancing bantahan. 'Aku merasa... ketika...' sulit dibantah karena itu pengalamanmu.",hint:"Menyampaikan dampak tanpa menuduh, atau menyerang?"},
{n:66,type:"tf",micro:"Asertif cocok untuk semua situasi?",q:"Benar atau Salah: Menyampaikan pendapat secara asertif selalu merupakan pilihan terbaik & aman di setiap situasi, tanpa perlu mempertimbangkan konteks.",answer:false,explain:"Sebaliknya, dalam situasi yang berbahaya (mis. berhadapan dengan orang yang mengancam kekerasan), menjaga keselamatan & mencari bantuan lebih utama daripada 'menang' berdebat. Asertif tetap butuh kebijaksanaan konteks.",hint:"Asertif selalu aman, atau tetap butuh membaca situasi?"},
{n:67,type:"mcq",micro:"Asertif & budaya/keluarga",q:"Di beberapa keluarga/budaya, menyampaikan ketidaksetujuan langsung ke orang yang lebih tua dianggap kurang sopan. Sikap bijak:",options:["Sesuaikan cara & bahasa (lebih halus, memilih waktu, memakai nada hormat) tanpa sepenuhnya membungkam kebutuhanmu","Tidak menyampaikan apa-apa kepada orang yang lebih tua, seberapa pun penting kebutuhanmu itu, demi sopan santun","Menyampaikan sekasar mungkin kepada mereka karena 'itu hakku', tanpa peduli kebiasaan sopan santun di keluargamu"],answer:0,explain:"Asertif menyesuaikan bentuk dengan norma yang berlaku, tapi tetap menemukan cara menyuarakan hal penting dengan hormat.",hint:"Sesuaikan bentuk + tetap bersuara, atau bungkam total / kasar?"},
{n:68,type:"mcq",micro:"Menilai apakah suatu batas sah",q:"Batas diri yang sehat biasanya...",options:["Berubah-ubah tiap jam sesuai suasana hati, supaya orang lain bingung dan tak bisa memperkirakan sikapmu","Melindungi kesejahteraanmu (waktu, tubuh, nilai, perasaan) tanpa bertujuan mengendalikan atau menghukum orang lain","Dipakai untuk memaksa dan mengendalikan orang lain agar mengikuti kehendakmu, serta menghukum bila melanggar"],answer:1,explain:"Batas: 'aku tidak akan...' atau 'kalau X terjadi, aku akan...'. Bukan 'kamu harus...' untuk mengendalikan.",hint:"Melindungi dirimu, atau mengendalikan orang?"},
{n:69,type:"mcq",micro:"Asertif & konflik yang sehat",q:"Mengapa kelompok yang anggotanya bisa asertif justru sering lebih kuat?",options:["Karena anggotanya jarang berkonflik, sehingga keputusan berjalan mulus tanpa perdebatan di dalam kelompok","Karena anggota yang paling keras suaranya menang, sehingga keputusan cepat diambil dan tak ada yang membantah","Masalah & ketidaksetujuan muncul ke permukaan lebih awal & bisa diselesaikan, bukan membusuk diam-diam"],answer:2,explain:"Konflik yang disuarakan dengan hormat adalah tanda kesehatan, bukan kegagalan, kelompok.",hint:"Masalah muncul & diselesaikan, atau membusuk diam?"},
{n:70,type:"order",micro:"Dari terpancing ke asertif",q:"Urutkan proses saat kamu merasa terpancing untuk merespons agresif.",items:["Kenali sinyal tubuh: dada panas, ingin membalas menyerang","Beri jeda: tarik napas, tunda respons beberapa detik","Rumuskan ulang dalam pernyataan 'aku': apa yang sebenarnya aku rasakan & butuhkan?","Sampaikan dengan tenang, atau tunda sampai kamu benar-benar bisa tenang"],answer:[0,1,2,3],explain:"Kenali → jeda → rumuskan 'aku' → sampaikan tenang atau tunda. Jeda adalah pemisah antara reaksi & respons.",hint:"Apa yang perlu kamu sadari sebelum bisa memberi jeda?"},
{n:71,type:"mcq",micro:"Asertif melindungi dari manipulasi",q:"Orang yang bisa asertif lebih tahan terhadap manipulasi karena...",options:["Mereka bisa berkata 'tidak', meminta waktu berpikir, & tidak mudah didorong rasa bersalah atau tekanan","Mereka tak punya perasaan, sehingga bujukan, tekanan, dan rasa bersalah tidak memengaruhi mereka di mana pun","Mereka curiga pada orang lain tanpa terkecuali, sehingga tak ada yang berani mencoba memanipulasi mereka"],answer:0,explain:"Manipulasi sering mengandalkan targetnya yang sulit menolak. Kemampuan menolak dengan tenang adalah perisai.",hint:"Bisa menolak & minta waktu, atau mudah didorong?"},
{n:72,type:"tf",micro:"Menyampaikan perasaan positif juga asertif",q:"Benar atau Salah: Komunikasi asertif hanya dipakai untuk menyampaikan keluhan atau ketidaksetujuan; mengungkapkan rasa sayang atau terima kasih tidak termasuk asertif.",answer:false,explain:"Sebaliknya, asertif adalah menyuarakan hal penting dengan jujur — termasuk hal-hal baik (sayang, terima kasih, kagum) yang sering kita tahan karena malu.",hint:"Asertif hanya untuk keluhan, atau juga untuk hal positif?"},
{n:73,type:"mcq",micro:"Ketika permintaanmu ditolak berulang",q:"Kamu sudah asertif tapi kebutuhanmu terus diabaikan dalam sebuah hubungan/kelompok. Pertimbangan berikutnya:",options:["Beralih ke gaya agresif saja, karena cara asertif sudah terbukti gagal & tidak ada lagi yang bisa dicoba","Menilai apakah hubungan/kelompok ini sehat & apakah perlu mengambil jarak, melibatkan pihak lain, atau mengubah situasi","Terus mengulang hal yang sama dan berharap suatu hari nanti orang lain berubah sendiri tanpa diajak bicara lagi"],answer:1,explain:"Asertif adalah usaha terbaikmu untuk menyampaikan. Kalau berulang kali diabaikan, keputusan berikutnya adalah tentang situasi itu sendiri.",hint:"Nilai situasinya & pertimbangkan langkah lain, atau ulang terus / jadi agresif?"},
{n:74,type:"mcq",micro:"Asertif & tanggung jawab atas perasaan",q:"Pernyataan 'aku' menempatkan tanggung jawab dengan tepat karena...",options:["Kamu bertanggung jawab atas perasaan orang-orang di sekitarmu, sehingga harus menjaga mereka tetap senang","Orang lain bertanggung jawab menebak sendiri kebutuhanmu tanpa kamu harus mengatakannya dengan jelas kepada mereka","Kamu bertanggung jawab menyampaikan perasaan & kebutuhanmu; orang lain bertanggung jawab atas respons mereka"],answer:2,explain:"Kamu tidak bisa mengontrol reaksi orang, tapi kamu bisa mengontrol apakah kamu menyuarakan dengan jelas & hormat.",hint:"Kamu menyuarakan, mereka merespons — atau kamu tanggung semuanya?"},
{n:75,type:"tf",micro:"Diam bukan selalu pasif",q:"Benar atau Salah: Memilih untuk tidak membahas sesuatu yang benar-benar kecil & tidak mengganggumu adalah keputusan yang sah, dan berbeda dari sikap pasif yang memendam hal penting.",answer:true,explain:"Asertif tidak berarti mengomentari segalanya. Membiarkan hal sepele lewat dengan sadar berbeda dari menahan hal yang benar-benar mengganjal.",hint:"Membiarkan hal sepele lewat = pasif, atau pilihan sadar yang sah?"},
{n:76,type:"mcq",micro:"Menilai kritik: asertif menerima & menyaring",q:"Sikap asertif terhadap kritik keras:",options:["Dengarkan, pisahkan isi yang berguna dari nada yang menyakitkan, ambil yang membangun, & sampaikan bila ada yang kamu lihat berbeda","Tolak seluruhnya karena disampaikan dengan kasar, sebab kritik yang menyakitkan biasanya tak ada isinya yang benar, lalu lupakan","Terima seluruhnya tanpa memilah dan mulai membenci diri sendiri, karena kritik keras menunjukkan kamu memang buruk dalam segalanya"],answer:0,explain:"Kamu bisa berkata: 'Cara penyampaiannya kurang enak buatku, tapi poin soal X aku terima & akan perbaiki.'",hint:"Pisahkan isi dari nada, atau tolak semua / telan semua?"},
{n:77,type:"mcq",micro:"Asertif di dunia digital",q:"Menyuarakan ketidaksetujuan di kolom komentar secara asertif (bukan agresif):",options:["Diam saja demi menghindari drama, meski yang dibahas hal penting dan kamu yakin ada yang keliru di dalamnya, lalu menyimpannya sendiri","Fokus pada gagasan ('menurutku data ini keliru karena...'), bukan menyerang pribadi; boleh memilih tidak terlibat kalau tidak sehat","Menghina & mempermalukan orang yang berbeda pendapat dengan kata-kata tajam supaya mereka berhenti berkomentar lagi"],answer:1,explain:"Prinsip sama: sampaikan posisi & alasan dengan hormat; kamu juga berhak menarik diri dari perdebatan yang tidak sehat.",hint:"Fokus gagasan + hormat, atau menyerang pribadi / bungkam total?"},
{n:78,type:"mcq",micro:"Asertif membantu kejujuran hubungan",q:"Hubungan di mana kedua pihak bisa asertif cenderung terasa...",options:["Lebih tegang dan rapuh, karena anggota harus berhati-hati dengan setiap kata yang diucapkan","Membosankan karena anggota hanya mengangguk dan jarang berselisih pendapat satu sama lain","Lebih aman & jujur, karena masing-masing tahu yang lain akan berkata jujur bila ada yang mengganjal"],answer:2,explain:"Kalau kamu tahu temanmu akan bilang kalau ada masalah, kamu tidak perlu menebak-nebak & khawatir terus.",hint:"Aman & jujur, atau tegang & rapuh?"},
{n:79,type:"mcq",micro:"Menilai 'nice' vs 'kind'",q:"Selalu 'baik' dengan mengiakan semua orang (people-pleasing) berbeda dari benar-benar peduli karena...",options:["Menyenangkan semua orang sering menyembunyikan kebutuhanmu & bisa membuatmu menipu diri; kepedulian sejati kadang berarti berkata jujur yang tidak menyenangkan","Keduanya sebenarnya sama, karena orang yang baik harus mengiakan permintaan orang lain tanpa menolak sedikit pun, demi menjaga kedamaian","Menyenangkan orang lain lebih baik daripada berkata jujur, karena kebutuhanmu sendiri tidak sepenting kebahagiaan orang di sekelilingmu, terutama dalam kelompok"],answer:0,explain:"Teman yang peduli akan berkata 'menurutku ini kurang tepat' meski berisiko mengecewakanmu sesaat.",hint:"Mengiakan semua = peduli, atau kadang menyembunyikan kebutuhan & kejujuran?"},
{n:80,type:"open",micro:"Membandingkan tiga respons",q:"Situasi: dalam antrean, seseorang menyerobot di depanmu. Tulis kemungkinan respons pasif, agresif, dan asertif, lalu jelaskan konsekuensi masing-masing dan mengapa asertif biasanya paling baik di sini.",explain:"Jawaban baik memberi tiga respons yang jelas berbeda dengan konsekuensinya masing-masing (pasif: terabaikan + menguatkan perilaku buruk; agresif: konflik + malu; asertif: fakta + hak tersampaikan, risiko kecil) dan menyimpulkan asertif paling efektif karena mencapai tujuan dengan biaya hubungan/harga diri terendah.",hint:"Untuk tiap gaya sebutkan kalimatnya + akibatnya; tunjukkan asertif mencapai tujuan dengan konflik paling kecil.",sample:"PASIF: diam saja, membiarkan orang itu menyerobot, lalu kesal sendiri sepanjang antre. Konsekuensi: kebutuhanku terabaikan, aku merasa diinjak, dan orang itu (mungkin tanpa sadar) belajar bahwa menyerobot berhasil. AGRESIF: 'Woy! Matamu di mana? Antre dong, nggak diajarin sopan santun ya?!' Konsekuensi: bisa memicu pertengkaran, mempermalukan diri sendiri juga, dan meski aku 'menang' suasananya jadi buruk. ASERTIF: dengan nada tenang, 'Maaf, sepertinya antreannya dari belakang sana. Saya sudah dari tadi di sini.' Konsekuensi: menyampaikan fakta dan hakku dengan jelas, memberi orang itu kesempatan memperbaiki tanpa merasa diserang; kebanyakan orang akan mundur. Kalau ia menolak, aku bisa melibatkan petugas dengan tenang. Asertif paling baik karena mencapai tujuan (hakku dalam antrean) dengan risiko konflik paling kecil dan tanpa mengorbankan harga diriku atau martabat orang lain."},
{n:81,type:"mcq",micro:"Kasus: asertif saat kamu salah",q:"Kamu menyadari kamu yang keliru di tengah perselisihan. Sikap asertif:",options:["Minta maaf sambil menyalahkan orang lain: 'Maaf, tapi kamu juga yang bikin aku jadi salah begini tadi.'","Akui dengan jelas: 'Kamu benar soal ini, aku yang salah. Maaf ya.' — tanpa berlebihan menyalahkan diri","Bersikeras bahwa kamu benar demi menjaga gengsi, walaupun kamu menyadari kekeliruanmu, lalu mengalihkan topik"],answer:1,explain:"Mengakui kesalahan dengan jujur & tenang adalah bentuk asertif — menghormati kebenaran & orang lain.",hint:"Akui jelas + minta maaf, atau ngotot / setengah minta maaf?"},
{n:82,type:"mcq",micro:"Kasus: tekanan dari figur otoritas untuk hal tidak etis",q:"Seorang senior/pelatih menyuruhmu melakukan sesuatu yang kamu yakini salah atau berbahaya. Sikap:",options:["Menuruti perintahnya tanpa membantah, karena ia senior dan lebih tahu, walaupun kamu yakin hal itu salah atau berbahaya, sebab menolak tidak sopan","Menuruti perintahnya sambil menyimpan dendam di dalam hati dan diam-diam membalasnya lewat cara tidak langsung di kemudian hari nanti","Sampaikan keberatanmu dengan hormat & jelas; kalau tetap dipaksa untuk hal serius/berbahaya, cari orang dewasa tepercaya lain untuk membantu"],answer:2,explain:"Asertif ke otoritas: hormat tapi jelas. Untuk hal yang membahayakan atau melanggar, melibatkan pihak lain yang tepercaya adalah langkah yang benar.",hint:"Keberatan hormat + cari bantuan bila serius, atau menurut buta?"},
{n:83,type:"tf",micro:"Refleksi: asertif adalah keterampilan seimbang",q:"Benar atau Salah: Menjadi asertif berarti menemukan titik seimbang — cukup berani menyuarakan diri, cukup peduli untuk menghormati orang lain — dan titik itu bisa dilatih seumur hidup.",answer:true,explain:"Bukan sekali jadi. Kadang kamu akan terlalu pasif, kadang terlalu keras; menyadari & menyesuaikan adalah bagian dari belajar.",hint:"Titik seimbang yang dilatih, atau sifat tetap?"},
{n:84,type:"mcq",micro:"Kasus: asertif untuk mengubah dinamika kelompok",q:"Kelompokmu selalu didominasi satu orang yang keras. Sebagai anggota, langkah asertif yang membangun:",options:["'Aku pengin dengar pendapat yang lain juga. Rina, Dito, gimana menurut kalian?' — membuka ruang tanpa menyerang si dominan","Diam saja & membiarkan dominasi orang itu berlanjut terus, karena kamu takut dimusuhi seluruh anggota kelompok","Menyerangnya di depan banyak orang: 'Kamu tuh nggak ngasih orang lain ngomong, egois banget jadi orang ya!'"],answer:0,explain:"Asertif bisa halus & strategis: alih-alih konfrontasi, kamu aktif membuka ruang untuk suara lain.",hint:"Buka ruang untuk yang lain, atau diam / menyerang si dominan?"},
{n:85,type:"order",micro:"Menyampaikan kekecewaan besar ke sahabat",q:"Urutkan langkah menyampaikan kekecewaan besar (sahabat membocorkan rahasiamu).",items:["Beri dirimu waktu menenangkan emosi dulu sebelum bicara","Ajak bicara berdua di tempat privat","Sampaikan pakai pernyataan 'aku': fakta + betapa dalam ini menyakitimu + apa artinya bagi kepercayaanmu","Dengarkan penjelasannya, lalu sampaikan apa yang kamu butuhkan ke depan"],answer:[0,1,2,3],explain:"Tenang dulu → tempat privat → 'aku' (fakta + luka + arti) → dengar + kebutuhan ke depan. Kekecewaan besar butuh ruang, bukan ledakan.",hint:"Apa yang harus tenang sebelum kamu bicara?"},
{n:86,type:"mcq",micro:"Kasus: batas dengan keluarga yang sulit",q:"Seorang anggota keluarga sering melontarkan komentar merendahkan tentang tubuhmu 'demi kebaikanmu'. Sikap asertif berkelanjutan:",options:["Membalas dengan menghina bentuk tubuh mereka juga di depan semua anggota keluarga, supaya mereka tahu rasanya direndahkan oleh orang lain","Sampaikan sekali dengan jelas bahwa komentar itu menyakitkan & kamu minta dihentikan; bila berlanjut, batasi topik atau waktu interaksi & cari dukungan orang tepercaya","Diam dan menahan perasaan setiap komentar itu muncul, tanpa mengatakan apa-apa kepada mereka, dan berharap mereka berhenti sendiri suatu hari nanti"],answer:1,explain:"Kamu tidak bisa memaksa orang berubah, tapi kamu bisa menyatakan batas, membatasi paparan, & mencari dukungan.",hint:"Nyatakan batas + batasi paparan + cari dukungan, atau menahan / membalas?"},
{n:87,type:"tf",micro:"Asertif tidak menjamin orang senang",q:"Benar atau Salah: Kalau seseorang kecewa saat kamu mulai bersikap asertif, itu tanda pasti bahwa batas yang kamu tetapkan salah & kamu harus kembali menuruti mereka.",answer:false,explain:"Sebaliknya, perubahan pola sering menimbulkan gesekan sementara. Reaksi kecewa orang yang terbiasa kamu turuti bukan bukti bahwa batas yang sehat itu keliru.",hint:"Reaksi kecewa orang = kamu salah, atau wajar saat pola berubah?"},
{n:88,type:"mcq",micro:"Kasus: menagih pengakuan atas kerja",q:"Kontribusi besarmu di proyek terus diklaim orang lain di depan guru. Langkah asertif:",options:["Diam dan membiarkan saja, lalu berharap guru menyadari sendiri siapa yang sebenarnya mengerjakan bagian itu, sambil mengurangi kontribusimu pada tugas berikutnya supaya orang itu merasakan akibatnya","Menjelekkan orang itu ke teman-teman lain di belakangnya, supaya mereka tahu ia mengaku-ngaku hasil kerjamu, lalu mengajak mereka menjauhinya sampai ia minta maaf, dan tak mau sekelompok lagi","Bicara langsung ke orang itu dulu: 'Aku merasa nggak enak waktu bagian yang aku kerjakan disebut sebagai kerjamu. Aku mau kontribusiku diakui.' Bila tak berubah, sampaikan fakta kontribusi ke guru dengan tenang"],answer:2,explain:"Mulai dari percakapan langsung yang asertif; eskalasi berbasis fakta bila perlu; hindari kampanye gosip.",hint:"Bicara langsung dulu + eskalasi fakta, atau diam / gosip?"},
{n:89,type:"mcq",micro:"Kasus: menyeimbangkan asertif & empati",q:"Temanmu, yang sedang berduka, berkali-kali membatalkan rencana mendadak & kamu mulai kesal. Sikap yang menyeimbangkan asertif & empati:",options:["'Aku ngerti kamu lagi berat & aku sayang kamu. Tapi pembatalan mendadak bikin aku susah rencana. Bisa kabari lebih awal kalau nggak sanggup?'","Memendam kekesalan demi memaklumi keadaannya, tanpa mengatakan apa-apa tentang perasaanmu kepadanya, sampai kamu sendiri kelelahan","'Kamu egois, cuma mikirin dukamu sendiri! Kamu nggak pernah mikir betapa repotnya aku tiap kali kamu membatalkan rencana!'"],answer:0,explain:"Empati & kebutuhanmu bisa hidup bersama: akui kesulitannya, tetap sampaikan dampaknya & minta perubahan kecil yang wajar.",hint:"Akui kesulitannya + sampaikan dampak + minta perubahan wajar, atau pendam / menyerang?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ditawari menjadi ketua panitia acara sekolah. Kamu ingin, tapi kamu tahu dirimu cenderung sulit menolak permintaan, akhirnya mengerjakan semuanya sendiri dan kelelahan. Rancang bagaimana kamu akan memakai komunikasi asertif sepanjang menjadi ketua agar tidak mengulang pola itu (minimal 6 praktik konkret).",explain:"Jawaban baik menyebut minimal 6 praktik asertif konkret: menetapkan norma tim di awal, pembagian tugas tertulis + konfirmasi, menolak mengambil alih tugas orang lain, teknik mengulang tenang tanpa rasa bersalah, batas waktu kerja pribadi yang ditepati, pernyataan 'aku' segera saat ada yang lalai (bukan memendam), meminta bantuan secara eksplisit, apresiasi spesifik.",hint:"Sasar pola 'sulit menolak': norma tim di awal, konfirmasi tugas, menolak ambil alih, mengulang tenang, batas waktu, 'aku' segera, minta bantuan eksplisit.",sample:"(1) Di awal, aku menyampaikan secara terbuka ke panitia: 'Aku mau kita kerja sebagai tim. Aku akan membagi tugas dan berharap masing-masing pegang bagiannya.' — menetapkan norma sejak awal. (2) Membuat pembagian tugas tertulis dengan nama dan tenggat, lalu mengonfirmasi tiap orang: 'Kamu oke pegang bagian ini sampai Rabu?' (3) Ketika ada yang meminta aku 'ambil alih saja' bagiannya, aku menahan dorongan menyanggupi otomatis: 'Aku nggak bisa ambil bagianmu. Kalau kamu kesulitan, ayo kita cari cara atau minta bantuan anggota lain.' (4) Memakai teknik mengulang tenang saat dibujuk, tanpa merasa bersalah dan tanpa alasan berlebihan. (5) Menetapkan batas waktu kerjaku sendiri: 'Aku bantu koordinasi sampai jam 5, setelah itu aku istirahat' — dan menepatinya. (6) Saat seseorang tidak mengerjakan bagiannya, aku menyampaikan dengan pernyataan 'aku' segera, bukan memendam sampai meledak: 'Bagianmu belum jalan dan itu bikin jadwal kita mundur. Aku butuh update hari ini.' (7) Meminta bantuan secara eksplisit ketika aku kewalahan, alih-alih diam-diam menanggung: 'Aku butuh dua orang bantu urus konsumsi, siapa bisa?' (8) Di akhir, memberi apresiasi spesifik ke anggota yang menepati tanggung jawabnya, supaya pola kerja tim yang sehat menguat."},
{n:91,type:"mcq",micro:"Kasus: asertif vs menyerah demi 'damai'",q:"Kelompokmu memutuskan sesuatu yang kamu yakini berisiko merugikan orang lain. Semua sudah setuju & kamu takut merusak suasana. Sikap:",options:["Mengomel kepada orang lain setelah rapat selesai tanpa pernah menyampaikan keberatanmu secara langsung di dalam rapat itu, lalu berharap ada yang mengubah keputusannya","Sampaikan keberatanmu sekali dengan jelas & alasannya, meski suara minoritas: 'Aku ngerti kalian sepakat, tapi aku khawatir soal X. Aku mau ini tercatat.'","Ikut setuju saja demi menjaga suasana tetap baik, walaupun kamu yakin keputusan itu berisiko merugikan orang lain & tidak mau ambil risiko dimusuhi kelompok"],answer:1,explain:"Asertif kadang berarti menjadi satu-satunya yang bersuara. Menyampaikan sekali dengan jelas & alasan sudah memenuhi tanggung jawabmu.",hint:"Suarakan keberatan sekali dengan jelas, atau ikut / mengomel di belakang?"},
{n:92,type:"tf",micro:"Refleksi: asertif melayani hubungan",q:"Benar atau Salah: Komunikasi asertif, dalam jangka panjang, cenderung membuat hubungan lebih sehat daripada gaya pasif atau agresif, karena masalah dibicarakan dengan jujur & hormat sebelum menumpuk.",answer:true,explain:"Hubungan terkuat bukan yang tanpa konflik, melainkan yang bisa membicarakan konflik dengan aman.",hint:"Asertif merusak atau menyehatkan hubungan jangka panjang?"},
{n:93,type:"mcq",micro:"Kasus: menyampaikan 'tidak' pada permintaan berulang orang tersayang",q:"Adikmu terus meminjam uang jajanmu & tidak pernah mengembalikan. Kamu sayang dia. Sikap asertif:",options:["Terus meminjamkan uang kepadanya sambil menahan kesal di dalam hati, dan tak mengatakan keberatanmu kepadanya sampai uangmu habis","'Dasar adik nyusahin! Kerjanya cuma bisa minta uang terus, aku nggak mau lagi punya adik seperti kamu ini!'","'Aku sayang kamu, tapi aku nggak akan minjemin lagi karena yang dulu-dulu nggak dikembalikan. Kalau kamu butuh, kita bicara sama Ibu.'"],answer:2,explain:"Kasih sayang & batas bisa berjalan bersama. Menolak dengan jelas + mengarahkan ke solusi yang tepat.",hint:"Sayang + batas jelas + arahkan solusi, atau menuruti / menghina?"},
{n:94,type:"mcq",micro:"Kasus: kamu terlanjur agresif",q:"Kamu baru saja meledak & berkata kasar ke teman karena kesal. Langkah pemulihan yang asertif & dewasa:",options:["'Maaf ya, tadi aku ngomongnya kasar & itu nggak pantas. Aku memang kesal soal X, tapi harusnya aku sampaikan dengan lebih baik.'","Pura-pura tidak terjadi apa-apa & berharap temanmu cepat melupakan kata-kata kasar yang tadi kamu ucapkan kepadanya","Menyalahkan temanmu karena ia 'sudah memancing' kemarahanmu, sehingga kamu merasa tidak perlu meminta maaf kepadanya"],answer:0,explain:"Asertif termasuk memperbaiki kesalahanmu sendiri: minta maaf atas cara, tetap boleh menyampaikan isi kekesalan dengan benar.",hint:"Minta maaf atas cara + sampaikan ulang dengan baik, atau abaikan / menyalahkan?"},
{n:95,type:"tf",micro:"Hak-hak asertif dasar",q:"Benar atau Salah: Hak untuk berkata 'tidak', mengubah pikiran, meminta waktu, atau meminta apa yang dibutuhkan hanya dimiliki orang dewasa atau orang yang berkuasa, bukan kamu.",answer:false,explain:"Sebaliknya, 'hak-hak asertif dasar' ini milik setiap orang, selama kamu juga menghormati hak yang sama pada orang lain. Menyadarinya melawan rasa bersalah yang tidak perlu.",hint:"Hak-hak ini nyata & timbal balik, atau hanya untuk orang lain?"},
{n:96,type:"mcq",micro:"Kasus: refleksi setelah percakapan",q:"Cara melatih asertif lewat refleksi:",options:["Menyimpulkan bahwa orang lain yang salah dalam setiap interaksi, sehingga kamu tak perlu mengubah apa-apa pada sikapmu, lalu lanjut seperti biasa","Setelah interaksi penting, tanya diri: apakah tadi aku terlalu pasif (menahan), terlalu agresif (menyerang), atau pas? apa yang akan kucoba beda?","Mengevaluasi diri hanya bila ada yang menegur, karena menurutmu cara bicaramu sudah tepat dan cukup, jadi tidak perlu dipikirkan setelahnya"],answer:1,explain:"Menilai diri di antara tiga kutub (pasif–asertif–agresif) mengubah tiap interaksi menjadi latihan yang terarah.",hint:"Evaluasi jujur di antara tiga gaya, atau tak pernah meninjau?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti menyampaikan pendapat & perasaan (asertif):",options:["Mengalah agar tak ada konflik, atau sebaliknya menekan agar kamu yang menang, mana yang terasa lebih mudah bagimu saat itu, tanpa memikirkan perasaan orang lain dalam interaksi tersebut, dan itu dianggap wajar","Utamakan perasaan sendiri di atas segalanya, abaikan hak orang lain untuk menolak, dan anggap batas orang lain tidak penting karena kebutuhanmu paling utama dalam setiap situasi yang kamu hadapi sehari-hari","Suarakan pendapat, perasaan, & kebutuhanmu dengan jujur & jelas — pakai pernyataan 'aku', tetapkan batas yang sehat, hormati hak orang lain untuk menolak, tanpa menjadi pasif (menahan) atau agresif (menyerang)"],answer:2,explain:"Ringkasan: jujur + jelas + hormat; pernyataan 'aku'; batas sehat; menerima 'tidak'; hindari dua ekstrem.",hint:"Jujur, jelas, hormat, 'aku', batas, terima 'tidak' — rangkai."},
{n:98,type:"tf",micro:"Refleksi: keberanian & kepedulian",q:"Benar atau Salah: Inti sikap asertif adalah menggabungkan keberanian (untuk menyuarakan diri) dengan kepedulian (untuk tetap menghormati orang lain).",answer:true,explain:"Keberanian tanpa kepedulian jadi agresif; kepedulian tanpa keberanian jadi pasif. Asertif butuh keduanya.",hint:"Keberanian + kepedulian bersama, atau salah satu saja?"},
{n:99,type:"mcq",micro:"Kasus: memulai kebiasaan asertif",q:"Cara termudah mulai melatih asertif:",options:["Pilih satu situasi kecil rutin (mis. menyatakan preferensi tempat makan, mengembalikan barang yang salah) & latih menyuarakannya dengan tenang minggu ini","Langsung menghadapi konflik terbesar dalam hidupmu sekarang juga, tanpa latihan kecil dan tanpa memikirkan akibatnya bagi hubungan dengan orang itu","Menunggu sampai kamu merasa 100% siap dan tak takut lagi, baru mencoba bersikap asertif kepada orang lain suatu hari nanti"],answer:0,explain:"Keberanian tumbuh dari kemenangan kecil yang berulang, bukan dari satu lompatan besar.",hint:"Latih di situasi kecil dulu, atau langsung yang terberat / menunggu siap?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi asertif",q:"Tulis 'aturan pribadi bersikap asertif' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: pakai pernyataan 'aku' & jangan memendam, berhak menolak sopan tanpa rasa bersalah, hormati 'tidak' orang lain, tunda saat emosi tinggi, tetapkan batas + konsekuensi yang ditepati, suarakan hal positif juga, refleksi di antara pasif–asertif–agresif.",hint:"Ambil satu pelajaran tiap fase — pernyataan 'aku', berhak menolak, hormati 'tidak', tunda saat emosi, batas + konsekuensi, hal positif, refleksi — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Kalau ada yang mengganjal, aku menyampaikannya dengan pernyataan 'aku' (situasi + perasaan + permintaan), bukan memendam sampai meledak — karena orang tidak bisa memperbaiki yang tidak mereka ketahui. (2) Aku boleh berkata 'tidak' dengan sopan tanpa alasan panjang & tanpa merasa bersalah — karena menolak dengan hormat bukan berbuat jahat. (3) Aku menghormati 'tidak' dari orang lain juga, tanpa memaksa atau merajuk — karena hak bersuara berlaku dua arah. (4) Kalau aku terlalu marah untuk bicara baik, aku menunda dengan menyebut waktu ('kita bahas nanti setelah aku tenang') — supaya aku tidak jadi agresif. (5) Aku menetapkan batas yang melindungi waktu, tubuh, nilai, & perasaanku, dan menyebut konsekuensinya bila dilanggar — lalu menepatinya. (6) Aku juga menyuarakan hal positif secara spesifik (terima kasih, apresiasi, sayang) — karena asertif bukan cuma soal keluhan. (7) Setelah percakapan penting, aku menilai: tadi aku terlalu pasif, terlalu agresif, atau pas? — supaya aku terus belajar."},
];
